package glitch

import data.glitch_lib

encryption_keywords := {"algorithm", "cipher", "encryption", "key", "password", "token", "secret", "salt", "iv", "nonce", "protocol", "tls", "ssl", "hash", "md5", "sha1", "encrypt", "cipher", "crypto", "auth"}
weak_algorithms := {"DES", "3DES", "RC4", "AES-128", "MD5", "SHA1", "SHA-1"}
outdated_protocols := {"SSLv3", "TLSv1.0", "TLSv1.1", "TLS1.0", "TLS1.1"}
weak_settings := {"none", "false", "disabled", "sse-s3", "no", "null", "off"}

contains_any(str, set) {
    set[_] = item
    regex.match(sprintf("(?i).*%s.*", [item]), str)
}

is_encryption_related(name) {
    contains_any(name, encryption_keywords)
}

check_weak_algorithm(value) {
    value.ir_type == "String"
    contains_any(value.value, weak_algorithms)
}

check_weak_algorithm_func(value) {
    value.ir_type == "FunctionCall"
    contains_any(value.name, weak_algorithms)
}

check_weak_algorithm_args(value) {
    value.ir_type == "FunctionCall"
    arg := value.args[_]
    arg.ir_type == "String"
    contains_any(arg.value, weak_algorithms)
}

check_insufficient_key_length(value) {
    value.ir_type == "Integer"
    value.value < 128
}

check_insufficient_key_length(value) {
    value.ir_type == "Integer"
    value.value == 1024
}

check_insufficient_key_length_str(value) {
    value.ir_type == "String"
    regex.match("^[0-9]{1,2}$", value.value)
    to_number(value.value) < 128
}

check_insufficient_key_length_str(value) {
    value.ir_type == "String"
    value.value == "1024"
}

check_outdated_protocol(value) {
    value.ir_type == "String"
    contains_any(value.value, outdated_protocols)
}

check_hardcoded_key(value) {
    value.ir_type == "String"
    not glitch_lib.traverse_var(value)
    value.value != ""
}

check_misconfigured_encryption_bool(value) {
    value.ir_type == "Boolean"
    value.value == false
}

check_misconfigured_encryption_str(value) {
    value.ir_type == "String"
    contains_any(value.value, weak_settings)
}

